def compute_edges(n, start, end):
    # n vertices
    d = [0]*(n+1)  # 1-indexed
    for i in range(1,n+1):
        if i%2==1:  # odd
            if i==start or i==end:
                d[i]=1
            else:
                d[i]=2
        else:
            d[i]=0
    e=[0]*(n)  # e[1..n-1]
    # compute e sequentially
    e[1]=d[1]  # e1 = d1
    if e[1] <0:
        return None
    for i in range(2,n):
        e[i]=d[i]-e[i-1]
        if e[i] <0:
            return None
    # check final condition: for vertex n, need e[n-1]==d[n]
    if e[n-1]!=d[n]:
        return None
    total=sum(e[1:])  # ignore index 0
    return total, e[1:]

